ALTER TABLE public.personal_profiles ADD COLUMN IF NOT EXISTS banner_fit text NOT NULL DEFAULT 'cover' CHECK (banner_fit IN ('cover', 'contain')); GRANT UPDATE (banner_fit) ON public.personal_profiles TO authenticated; GRANT UPDATE (banner_fit) ON public.personal_profiles TO service_role; GRANT SELECT (banner_fit) ON public.personal_profiles TO anon, authenticated, service_role; UPDATE public.personal_profiles SET banner_fit = 'cover' WHERE header_type = 'banner' AND banner_fit IS NULL;